    struct Color {};

    // Module 2 (Revised)
    class Door {
    public:
        Door(DoorState initial_state, Color color) : state_(initial_state), color_(color) {}

        void open() {
            if (state_ != DoorState::Closed) {
                throw std::domain_error("Door is already open.");
            }
            state_ = DoorState::Open;
        }

        void close() {
            state_ = DoorState::Closed;
        }

        Color color() const { return color_; }
        void setColor(Color c) { color_ = c; }

        std::string toString() const { return "Door [color: " + color_ + ", state: " + toString(state_) + "]"; }

    private:
        DoorState state_;
        Color color_;

        // Helper function for state representation
        static std::string toString(DoorState state) {
            switch (state) {
                case DoorState::Open: return "Open";
                case DoorState::Closed: return "Closed";
                default: return "Unknown";
            }
        }
    };

    enum class DoorState {
        Open,
        Closed
    };
    ```

